G=load()

def transform(grid):
    from collections import deque
    h,w=len(grid),len(grid[0])
    bg=grid[0][0]
    seen=[[False]*w for _ in range(h)]
    out=[row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=bg and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; comp=[]
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and grid[ny][nx]!=bg:
                            seen[ny][nx]=True; q.append((ny,nx))
                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                t_,b,l,r=min(ys),max(ys),min(xs),max(xs)
                area=(b-t_-1)*(r-l-1)
                fill=2 if area%2==0 else 7
                for y in range(t_+1,b):
                    for x in range(l+1,r):
                        out[y][x]=fill
    return out

